head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/MAP/data/MAP_SUBCHART.json";   // {json:[...기본 지역...]}
scwin.CHART_CONFIG = {
    dataOpts: {
        keys: { x: "code", value: ["강수량"] }
    },
    extend: {
        map: {
            mapUrl: "/websquare/_websquare_/externalJS/sbchart/SIGUNGU.json",
            subchart: {                                         // ★ 지역 위 서브차트
                show: true,
                type: "bar",
                basePosition: "zero",
                subDatas: [
                    {
                        position: { code: 32 },                 // 강원 위에 표시
                        data: {
                            type: "pie",
                            json: [ { "name": "seoul", "2015": 490, "2016": 1200, "2017": 300 } ],
                            keys: { x: "name", value: ["2015","2016","2017"] }
                        }
                    }
                ]
            }
        }
    }
};

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData("map", data, chartWrap, scwin.CHART_CONFIG);
};
